package de.ga36.home;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.widget.*;
public final class GameActionsActivity extends ConsolePanel {
 static boolean game(Context c,String pkg){if(pkg==null)return false;try{return HomeActivity.candidate(pkg,c.getPackageManager().getApplicationInfo(pkg,0).flags)&&c.getPackageManager().getLaunchIntentForPackage(pkg)!=null;}catch(PackageManager.NameNotFoundException e){return false;}}
 static void restart(Context c,String pkg){if(!game(c,pkg)){Toast.makeText(c,I18n.t("Kein laufendes Spiel erkannt"),0).show();return;}try{Intent launch=c.getPackageManager().getLaunchIntentForPackage(pkg);Object am=c.getSystemService(ACTIVITY_SERVICE);am.getClass().getMethod("forceStopPackage",String.class).invoke(am,pkg);c.startActivity(launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){android.util.Log.e("GA36Keys","RESTART_FAILED",e);Toast.makeText(c,I18n.t("Spiel konnte nicht neu gestartet werden"),1).show();}}
 public void finish(){finishAndRemoveTask();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);menu();}
 public void onCreate(Bundle b){super.onCreate(b);menu();}
 void menu(){panel.removeAllViews();final String pkg=getIntent().getStringExtra("game");if("restart".equals(getIntent().getStringExtra("command"))){restart(this,pkg);finish();return;}text(I18n.t("Spielmenü"),25);button(I18n.t("Fortsetzen"),new Runnable(){public void run(){finish();}});if(game(this,pkg))button(I18n.t("Spiel neu starten"),new Runnable(){public void run(){restart(GameActionsActivity.this,pkg);finish();}});if(game(this,pkg))button(I18n.t("Spiel beenden"),new Runnable(){public void run(){try{Object am=getSystemService(ACTIVITY_SERVICE);am.getClass().getMethod("forceStopPackage",String.class).invoke(am,pkg);startActivity(new Intent(GameActionsActivity.this,HomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}catch(Exception e){android.util.Log.e("GA36Keys","STOP_FAILED",e);Toast.makeText(GameActionsActivity.this,I18n.t("Spiel konnte nicht beendet werden"),1).show();}}});button(I18n.t("Zum Launcher"),new Runnable(){public void run(){startActivity(new Intent(GameActionsActivity.this,HomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}});button(I18n.t("FN-Belegung"),new Runnable(){public void run(){startActivity(new Intent(GameActionsActivity.this,KeysActivity.class));}});}
}
